spec=importlib.util.spec_from_file_location('source_evidence',ROOT/'tools/verify_implementation_evidence.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
sha=lambda b:hashlib.sha256(b).hexdigest()
CANON=ROOT/'archive/PRAIN_v0.99.6_Phase0_Green_Closure.zip'
z=zipfile.ZipFile(CANON)
canonical={Path(n).name:(n,z.read(n)) for n in z.namelist() if not n.endswith('/')}

def reference(basename,section=None):
    name,data=canonical[basename];lines=data.decode().splitlines();start=1;end=len(lines)
    if section:
        start=next(i+1 for i,s in enumerate(lines) if s.startswith('#') and section in s)
        level=len(lines[start-1])-len(lines[start-1].lstrip('#'))
        end=next((i for i in range(start,len(lines)) if lines[i].startswith('#') and len(lines[i])-len(lines[i].lstrip('#'))<=level),len(lines))
    return {'archive':str(CANON.relative_to(ROOT)),'archive_sha256':sha(CANON.read_bytes()),'member':name,'sha256':sha(data),'start_line':start,'end_line':end,'section':section}

