for row in rows:
    source=row['source'];path=source['path'];uid=row['requirement_id'];name=Path(path).name
    if path not in cache:cache[path]=m.read_source(path)[0]
    data=cache[path];lines=data.decode().splitlines();line=source['line'];assert lines[line-1].strip()==row['text'];assert sha(data)==source['sha256']
    common={'requirement_id':uid,'source':source,'text':row['text'],'source_context_sha256':sha(data),'reviewer':'normative_b independent semantic/version review agent','runtime_acceptance':'NOT_ACCEPTED','production_acceptance':False,'review_method':'Explicit control assignment for exact operative text; full-schema binding for schema nodes; structural heading assessment with section preserved.'}
    if '/contracts/' in path:
        detail,code,test,gap=SCHEMA_DETAILS[name];target_name,target_data=canonical[name];assert data==target_data
        ptr=source.get('json_pointer_context',{}).get('pointer','')
        common.update(disposition='RETAIN',effective_normative_version='canonical v0.99.6 / contract1.0.0',canonical_references=[reference(name)],canonical_json_pointer=ptr,standalone_obligation=False,
            rationale=f'This row is part of the complete {name} contract, byte-identical in the canonical release. Reviewed contract meaning: {detail} Node {ptr or "/"} is evaluated only within parent required/properties/conditional composition; formatting and annotations do not create independent obligations.',
            implementation_evidence=[{'path':p,'sha256':sha((ROOT/p).read_bytes()),'scope':'Partial related implementation/test only; not canonical contract conformance.'} for p in (code,test)],missing_proof=gap,
            section_obligations_status='RETAINED_CANONICAL_CONTRACT_RUNTIME_UNVERIFIED')
    elif row['text'].startswith('#'):
        level=len(row['text'])-len(row['text'].lstrip('#'));end=next((i for i in range(line,len(lines)) if lines[i].startswith('#') and len(lines[i])-len(lines[i].lstrip('#'))<=level),len(lines));section='\n'.join(lines[line-1:end]);c=DOC_CONTROL[name];b,s,reason,gap=CONTROLS[c]
        key=f'{sha(data)}:{line}:{end}'
        context_dossiers[key]={'source_path':path,'start_line':line,'end_line':end,'source_sha256':sha(data),'section_sha256':sha(section.encode()),'heading':row['text'],'semantic_control':c,'reviewed_control_meaning':reason,'section_runtime_obligations':'PRESERVED_NOT_DISCHARGED','missing_proof':gap,'canonical_support':reference(b,s)}
        common.update(disposition='NON_NORMATIVE',effective_normative_version='structural source heading, not a standalone behavioral requirement',canonical_references=[reference(b,s)],standalone_obligation=False,section_context_key=key,
            rationale=f'The exact candidate is a document/section heading rather than a proposition or constraint. Its complete source section ({line}–{end}) is preserved under the reviewed control scope {c}: {reason} No underlying normative body is superseded or marked implemented by this heading classification.',
            missing_proof=gap,section_obligations_status='PRESERVED_AND_RUNTIME_UNVERIFIED')
    else:
        assert row['text'] in text_assign,(uid,row['text'])
        reviewed_id,c=text_assign[row['text']];b,s,reason,gap=CONTROLS[c];disp='RETAIN';standalone=True
        if c in ('STATUS','AUDIT') or uid in ('RTM-01636','RTM-02376','RTM-01953') or reviewed_id in (1636,2376,1953):disp='NON_NORMATIVE';standalone=False
        if reviewed_id in (1777,1778,1779,1780,1781,1782,1783,1784):disp='SUPERSEDE';reason='The old unchecked specification-choice item is superseded by an explicit canonical decision; its implementation obligation remains retained. '+reason
        if reviewed_id==1795:disp='SUPERSEDE';reason='The legacy evidence-or-exception alternative is superseded by canonical verified=passed+verification_ref: a documented exception is review context, never verification success. '+reason
        if reviewed_id in (2066,2058,2253):disp='SUPERSEDE';reason='The historical proposed/unreconciled specification decision state is replaced for the archived Phase0 baseline by v0.99.6 canonical decisions/contracts; present runtime/production approval is still separate. '+reason
        common.update(disposition=disp,effective_normative_version='canonical v0.99.6 supporting section plus retained original detail where not explicitly replaced',canonical_references=[reference(b,s)],standalone_obligation=standalone,reviewed_exact_text_reference=f'RTM-{reviewed_id:05d}',semantic_control=c,rationale=reason,missing_proof=gap,section_obligations_status='RETAINED_RUNTIME_UNVERIFIED' if standalone else 'CONTEXT_ONLY_UNDERLYING_CONTROL_RETAINED')
    if common.get('semantic_control') in ('ID', 'TIME'):
        legacy_archive=ROOT/'archive/PRAIN_Phase0_v0.2.1.zip'
        with zipfile.ZipFile(legacy_archive) as legacy:
            legacy_member=next(n for n in legacy.namelist() if n.endswith('/docs/DECISION_REGISTER.md'))
            legacy_data=legacy.read(legacy_member)
        target='## DEC-001' if common['semantic_control']=='ID' else '## DEC-002'
        legacy_lines=legacy_data.decode().splitlines()
        first=next(i+1 for i,l in enumerate(legacy_lines) if l.startswith(target))
        last=next((i for i in range(first,len(legacy_lines)) if legacy_lines[i].startswith('## ')),len(legacy_lines))
        common['canonical_references'].insert(0,{'archive':str(legacy_archive.relative_to(ROOT)),'archive_sha256':sha(legacy_archive.read_bytes()),'member':legacy_member,'sha256':sha(legacy_data),'start_line':first,'end_line':last,'section':target,'relationship':'PRESERVED_EXPLICIT_LEGACY_DECISION; not numbered as a different canonical decision'})
    common['canonical_reference'] = common['canonical_references'][0]
    common['implementation_status'] = 'NOT_APPLICABLE' if common['disposition'] == 'NON_NORMATIVE' else 'OPEN'
    common['source_sha256'] = sha(data)
